contract InvMutTest {
  C c;

  constructor(C _c) {
    c = _c;
  }

  function run(address newRoundImplementation) public payable {
    require(!c.programOperators(address(this)));

    (bool ownerSuccess, bytes memory ownerData) = address(c).staticcall(abi.encodeWithSignature("owner()"));
    require(ownerSuccess && ownerData.length >= 32);
    address cOwner = abi.decode(ownerData, (address));
    require(cOwner != address(this));

    bool reverted;
    try c.updateRoundImplementation(payable(newRoundImplementation)) {
      reverted = false;
    } catch {
      reverted = true;
    }

    if (newRoundImplementation == address(0)) {
      assert(reverted);
    } else {
      assert(reverted || c.roundImplementation() == newRoundImplementation);
    }
  }
}

